#!/usr/bin/env python3
"""Gera apostila.html a partir do conteúdo abaixo. PDF: node render-pdf.mjs (ver README.md)."""
import html, os, sys
SH = os.environ["SHOTS"]
OUT = os.path.join(os.path.dirname(__file__), "apostila.html")
e = html.escape
parts = []; toc = []; n_sec = [0]

def H1(t, intro=""):
    n_sec[0] += 1; i = f"s{n_sec[0]}"; toc.append((1, i, t))
    parts.append(f'<section class="chap"><h1 id="{i}"><span class="num">{n_sec[0]}</span>{e(t)}</h1>{("<p class=lead>"+intro+"</p>") if intro else ""}')
def END(): parts.append("</section>")
def H2(t):
    i = f"h{len(toc)}"; toc.append((2, i, t)); parts.append(f'<h2 id="{i}">{e(t)}</h2>')
def P(t): parts.append(f"<p>{t}</p>")
def UL(items): parts.append("<ul>" + "".join(f"<li>{x}</li>" for x in items) + "</ul>")
def OL(items): parts.append("<ol>" + "".join(f"<li>{x}</li>" for x in items) + "</ol>")
def BOX(kind, title, t): parts.append(f'<div class="box {kind}"><b>{e(title)}</b><span>{t}</span></div>')
def IMG(name, cap, h=215):
    os.makedirs(os.path.join(os.path.dirname(__file__), "img"), exist_ok=True)
    import shutil; shutil.copy(f"{SH}/{name}.png", os.path.join(os.path.dirname(__file__), "img", f"{name}.png"))
    parts.append(f'<figure><img src="img/{name}.png" style="max-height:{h}mm"><figcaption>{e(cap)}</figcaption></figure>')
def FIELDS(rows, title="Campos desta tela"):
    """rows: (campo, obrigatório 'Sim'/'Não'/'—', o que é / o que informar, exemplo)"""
    h = f'<div class="ft"><div class="ftt">{e(title)}</div><table><thead><tr><th style="width:22%">Campo</th><th style="width:9%">Obrig.</th><th>O que faz e o que informar</th><th style="width:26%">Exemplo</th></tr></thead><tbody>'
    for c, o, d, x in rows:
        h += f'<tr><td><b>{c}</b></td><td class="c">{o}</td><td>{d}</td><td class="ex">{x}</td></tr>'
    parts.append(h + "</tbody></table></div>")
def RESULT(t): parts.append(f'<div class="box ok"><b>Resultado esperado</b><span>{t}</span></div>')
def EX(t): parts.append(f'<div class="box ex"><b>Exemplo de configuração</b><span>{t}</span></div>')
def TABLE(head, rows, widths=None):
    h = "<table class='gen'><thead><tr>" + "".join(f"<th>{x}</th>" for x in head) + "</tr></thead><tbody>"
    for r in rows: h += "<tr>" + "".join(f"<td>{x}</td>" for x in r) + "</tr>"
    parts.append(h + "</tbody></table>")

# ───────────────────────── 1. Introdução
H1("Como usar esta apostila", "Guia de consulta do Efettiva OS, tela por tela e campo por campo, com exemplos de preenchimento e do resultado esperado. Todas as imagens vêm do próprio sistema com dados fictícios (selo DEMO).")
