OL(["<b>Cadastrar o cliente</b> (Clientes → Novo cliente).", "<b>Diagnosticar</b>: responder o questionário 360° e fechar o diagnóstico.", "<b>Importar dados</b> comerciais (opcional, mas dá números reais às oportunidades).", "<b>Registrar oportunidades</b> e priorizá-las (Impacto × Confiança ÷ Esforço).", "<b>Criar o projeto</b> com plano 30/60/90 e tarefas a partir dos processos da biblioteca.", "<b>Gerar o playbook</b>, editar por seções, aprovar e exportar em DOCX/PDF/MD.", "<b>Acompanhar</b>: baseline, snapshots, auditorias, reuniões e <b>relatório de resultados</b>."])
H2("Convenções usadas")
TABLE(["Marca", "Significado"], [["<b>*</b> / “Obrig.: Sim”", "Campo obrigatório. O sistema não grava sem ele."], ["<span class='tag demo'>DEMO</span>", "Dado fictício de demonstração. Nunca é misturado com dados reais."], ["<b>[PENDENTE: …]</b>", "Lacuna em um documento gerado. Precisa ser confirmada com o cliente antes de aprovar."], ["<b>Indisponível</b> / <b>n/d</b>", "O sistema não tem dado suficiente e prefere mostrar “sem dado” a inventar um número."], ["<b>INTERNO</b> × <b>Cliente</b>", "Visibilidade de uma seção: INTERNO nunca sai no arquivo entregue ao cliente."]])
