# ───────────────────────── 14. Glossário e problemas
H1("Glossário e solução de problemas")
H2("Glossário")
TABLE(["Termo", "Significado"], [["Achado", "Constatação do diagnóstico ou dos dados (problema, risco, oportunidade, ponto forte, lacuna)."], ["Baseline", "Retrato dos indicadores nos 90 dias anteriores ao início do projeto, congelado e imutável."], ["Snapshot", "Retrato dos indicadores em uma data, guardado para comparação."], ["Gate", "Critério mínimo para encerrar uma fase do método."], ["POP", "Procedimento operacional padrão de um processo."], ["Playbook", "Documento que reúne diagnóstico, prioridades, processos, KPIs e cronograma."], ["Score de prioridade", "Impacto × Confiança ÷ Esforço (máximo 25)."], ["Observado / Estimado / Meta", "Classificação do valor: dado real, cálculo com premissas ou objetivo."], ["Lote", "Um arquivo importado, com status e resultado."], ["Job", "Tarefa em segundo plano (importar, exportar, IA)."]])
H2("Problemas comuns")
TABLE(["Sintoma", "Causa provável", "O que fazer"], [["Botão “Aprovar versão” desativado", "Há seções não aprovadas ou erro na checagem de qualidade.", "Aprove cada seção e corrija os itens com ✕ na checagem."], ["Indicador “Indisponível”", "Falta dado (ex.: custo variável) ou período curto.", "Leia o motivo no cartão e complete a importação."], ["“Salvar mapeamento” bloqueado", "Campo obrigatório sem coluna.", "Mapeie os campos marcados com *."], ["Importação rejeitou linhas", "Status desconhecido, data ou moeda fora do formato.", "Baixe o CSV de erros, corrija e reenvie (não duplica)."], ["“Sugerir com IA” desativado", "IA desligada, sem chave ou sem autorização do cliente.", "Configurações → IA e Editar cadastro → Autorizar IA externa."], ["Exportação demora ou falha", "Worker parado ou job com falha.", "Backups e saúde → Testar fila; use Tentar de novo."], ["Acesso bloqueado ao entrar", "5 tentativas erradas.", "Aguarde 15 minutos."], ["Cliente “não encontrado”", "Sem permissão ou ID de outro cliente.", "Volte pelo seletor de cliente."]])
END()

